window.MG_LAZY_DATA["data/lazy/courses/v11-kibali-mine-8c437c644cc6d681.json"]={sha256:"8c437c644cc6d6812d54e361a915d779602afdce6d29eb4bc498a1affe56bac1",value:{"id":"v11-kibali-mine","title":"Kibali 大型金礦工程","titleEn":"Kibali large gold-mining engineering","category":"materials","subcategory":"resources-gold","subcategoryTitle":"金礦與砂金工程","subcategoryTitleEn":"Gold and placer engineering","learningTrack":"resources","learningSubdiscipline":"resources-gold","learningTags":["resources","resources-gold","kibali-mine"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-kibali","v11x-gold"],"stages":[{"id":"v11-kibali-mine-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Kibali 大型金礦工程案例中比較Kibali資源grade與露天地下path區別，各完成分析及驗證。","descriptionEn":"Analyze and validate kibali resource grades and surface/underground paths within the Kibali large gold-mining engineering case.","steps":[{"id":"v11-kibali-mine-v11-01","order":1,"sequence":1,"title":"資源品位與代表採樣：架構分析","titleEn":"Resources, grade and representative sampling: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":[],"objective":"針對Kibali資源grade提出可反駁的資源品位與代表採樣模型與驗證紀錄。","objectiveEn":"Produce a falsifiable resources, grade and representative sampling model and evidence record for kibali resource grades.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識Kibali資源grade。品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。 建立資源品位與代表採樣的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較加權平均品位與未加權平均。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify kibali resource grades in the mentor diagram and primary sources for Kibali large gold-mining engineering. Grades/samples have different confidence; a rich local sample is not a mine-wide estimate. Draw the inputs, states, outputs and boundaries of resources, grade and representative sampling, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare weighted and unweighted grade means. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較加權平均品位與未加權平均。","observationEn":"Compare weighted and unweighted grade means.","failure":"常見誤判：最好樣本的品位可代表所有礦石。","failureEn":"Common misconception: The best sample represents every ore parcel.","check":"提交Kibali資源grade的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for kibali resource grades.","knowledge":[{"id":"v11-kibali-mine-v11-01-k1","title":"資源品位與代表採樣","titleEn":"Resources, grade and representative sampling","text":"品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。 本課架構對應：Kibali資源grade","textEn":"Grades/samples have different confidence; a rich local sample is not a mine-wide estimate. Course architecture correspondence: Kibali resource grades","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較加權平均品位與未加權平均。 應逐項保留基準與不確定度；最好樣本的品位可代表所有礦石。 是本單元要排除的誤解。","textEn":"Compare weighted and unweighted grade means. Retain each reference and uncertainty; reject the misconception: The best sample represents every ore parcel.","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設乾給料1100 t、品位1.5 g/t、金屬回收率0.85，可回收金屬=1402.5 g=1.4025 kg。回收率不同於精礦品位；未含礦物解離、處理成本或任何浸出配方，非礦場實測。","textEn":"Assume dry feed 1100 t, grade 1.5 g/t and metal recovery 0.85: recovered metal 1402.5 g=1.4025 kg. Recovery differs from concentrate grade; liberation/costs and all leaching recipes are excluded; this is not a mine measurement.","sourceIds":["v11x-kibali","v11x-gold"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Kibali資源grade的「資源品位與代表採樣」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for resources, grade and representative sampling in kibali resource grades?","options":["品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。","最好樣本的品位可代表所有礦石。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Grades/samples have different confidence; a rich local sample is not a mine-wide estimate.","The best sample represents every ore parcel.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。 比較加權平均品位與未加權平均。","explanationEn":"Grades/samples have different confidence; a rich local sample is not a mine-wide estimate. Compare weighted and unweighted grade means."}},{"id":"v11-kibali-mine-v11-02","order":2,"sequence":2,"title":"資源品位與代表採樣：證據驗證","titleEn":"Resources, grade and representative sampling: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-01"],"objective":"針對Kibali資源grade提出可反駁的資源品位與代表採樣模型與驗證紀錄。","objectiveEn":"Produce a falsifiable resources, grade and representative sampling model and evidence record for kibali resource grades.","instruction":"沿用前一步「資源品位與代表採樣」模型，檢查Kibali資源grade的兩個假想案例。比較加權平均品位與未加權平均。 先訂可接受誤差，再比較預測與獨立計算；區分品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous resources, grade and representative sampling model to inspect two hypothetical cases involving kibali resource grades. Compare weighted and unweighted grade means. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Grades/samples have different confidence; a rich local sample is not a mine-wide estimate.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較加權平均品位與未加權平均。","observationEn":"Compare weighted and unweighted grade means.","failure":"常見誤判：最好樣本的品位可代表所有礦石。","failureEn":"Common misconception: The best sample represents every ore parcel.","check":"提交Kibali資源grade的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for kibali resource grades.","knowledge":[{"id":"v11-kibali-mine-v11-02-k1","title":"資源品位與代表採樣","titleEn":"Resources, grade and representative sampling","text":"品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。 本課架構對應：Kibali資源grade","textEn":"Grades/samples have different confidence; a rich local sample is not a mine-wide estimate. Course architecture correspondence: Kibali resource grades","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較加權平均品位與未加權平均。 應逐項保留基準與不確定度；最好樣本的品位可代表所有礦石。 是本單元要排除的誤解。","textEn":"Compare weighted and unweighted grade means. Retain each reference and uncertainty; reject the misconception: The best sample represents every ore parcel.","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設乾給料1100 t、品位1.5 g/t、金屬回收率0.85，可回收金屬=1402.5 g=1.4025 kg。回收率不同於精礦品位；未含礦物解離、處理成本或任何浸出配方，非礦場實測。","textEn":"Assume dry feed 1100 t, grade 1.5 g/t and metal recovery 0.85: recovered metal 1402.5 g=1.4025 kg. Recovery differs from concentrate grade; liberation/costs and all leaching recipes are excluded; this is not a mine measurement.","sourceIds":["v11x-kibali","v11x-gold"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Kibali資源grade的「資源品位與代表採樣」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for resources, grade and representative sampling in kibali resource grades?","options":["最好樣本的品位可代表所有礦石。","比較加權平均品位與未加權平均。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["The best sample represents every ore parcel.","Compare weighted and unweighted grade means.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"品位分佈與取樣支持不同置信度；局部高品位不能代替整礦估計。 比較加權平均品位與未加權平均。","explanationEn":"Grades/samples have different confidence; a rich local sample is not a mine-wide estimate. Compare weighted and unweighted grade means."}},{"id":"v11-kibali-mine-v11-03","order":3,"sequence":3,"title":"開坑地下與搬運：架構分析","titleEn":"Open-pit, underground and haulage: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-02"],"objective":"針對露天地下path區別提出可反駁的開坑地下與搬運模型與驗證紀錄。","objectiveEn":"Produce a falsifiable open-pit, underground and haulage model and evidence record for surface/underground paths.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識露天地下path區別。露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。 建立開坑地下與搬運的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。畫礦石、廢石與人員／設備分開的概念路徑。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify surface/underground paths in the mentor diagram and primary sources for Kibali large gold-mining engineering. Surface, underground and placer routes differ; haulage/support affect energy and risks. Draw the inputs, states, outputs and boundaries of open-pit, underground and haulage, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Draw separate conceptual ore, waste and people/equipment paths. Record units, undisclosed parameters and model breakdown conditions.","observation":"畫礦石、廢石與人員／設備分開的概念路徑。","observationEn":"Draw separate conceptual ore, waste and people/equipment paths.","failure":"常見誤判：露天與地下可沿用所有支護和搬運參數。","failureEn":"Common misconception: Surface and underground systems share every support/haulage parameter.","check":"提交露天地下path區別的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for surface/underground paths.","knowledge":[{"id":"v11-kibali-mine-v11-03-k1","title":"開坑地下與搬運","titleEn":"Open-pit, underground and haulage","text":"露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。 本課架構對應：露天地下path區別","textEn":"Surface, underground and placer routes differ; haulage/support affect energy and risks. Course architecture correspondence: Surface/underground paths","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫礦石、廢石與人員／設備分開的概念路徑。 應逐項保留基準與不確定度；露天與地下可沿用所有支護和搬運參數。 是本單元要排除的誤解。","textEn":"Draw separate conceptual ore, waste and people/equipment paths. Retain each reference and uncertainty; reject the misconception: Surface and underground systems share every support/haulage parameter.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就露天地下path區別的「開坑地下與搬運」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for open-pit, underground and haulage in surface/underground paths?","options":["露天與地下可沿用所有支護和搬運參數。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。"],"optionsEn":["Surface and underground systems share every support/haulage parameter.","Equal case averages rule out spatial, temporal and model errors.","Surface, underground and placer routes differ; haulage/support affect energy and risks."],"answer":2,"explanation":"露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。 畫礦石、廢石與人員／設備分開的概念路徑。","explanationEn":"Surface, underground and placer routes differ; haulage/support affect energy and risks. Draw separate conceptual ore, waste and people/equipment paths."}},{"id":"v11-kibali-mine-v11-04","order":4,"sequence":4,"title":"開坑地下與搬運：證據驗證","titleEn":"Open-pit, underground and haulage: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-03"],"objective":"針對露天地下path區別提出可反駁的開坑地下與搬運模型與驗證紀錄。","objectiveEn":"Produce a falsifiable open-pit, underground and haulage model and evidence record for surface/underground paths.","instruction":"沿用前一步「開坑地下與搬運」模型，檢查露天地下path區別的兩個假想案例。畫礦石、廢石與人員／設備分開的概念路徑。 先訂可接受誤差，再比較預測與獨立計算；區分露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous open-pit, underground and haulage model to inspect two hypothetical cases involving surface/underground paths. Draw separate conceptual ore, waste and people/equipment paths. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Surface, underground and placer routes differ; haulage/support affect energy and risks.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"畫礦石、廢石與人員／設備分開的概念路徑。","observationEn":"Draw separate conceptual ore, waste and people/equipment paths.","failure":"常見誤判：露天與地下可沿用所有支護和搬運參數。","failureEn":"Common misconception: Surface and underground systems share every support/haulage parameter.","check":"提交露天地下path區別的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for surface/underground paths.","knowledge":[{"id":"v11-kibali-mine-v11-04-k1","title":"開坑地下與搬運","titleEn":"Open-pit, underground and haulage","text":"露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。 本課架構對應：露天地下path區別","textEn":"Surface, underground and placer routes differ; haulage/support affect energy and risks. Course architecture correspondence: Surface/underground paths","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫礦石、廢石與人員／設備分開的概念路徑。 應逐項保留基準與不確定度；露天與地下可沿用所有支護和搬運參數。 是本單元要排除的誤解。","textEn":"Draw separate conceptual ore, waste and people/equipment paths. Retain each reference and uncertainty; reject the misconception: Surface and underground systems share every support/haulage parameter.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就露天地下path區別的「開坑地下與搬運」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for open-pit, underground and haulage in surface/underground paths?","options":["畫礦石、廢石與人員／設備分開的概念路徑。","露天與地下可沿用所有支護和搬運參數。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Draw separate conceptual ore, waste and people/equipment paths.","Surface and underground systems share every support/haulage parameter.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"露天、地下與重力砂金路徑的邊界不同；搬運與支撐影響能量和風險。 畫礦石、廢石與人員／設備分開的概念路徑。","explanationEn":"Surface, underground and placer routes differ; haulage/support affect energy and risks. Draw separate conceptual ore, waste and people/equipment paths."}}]},{"id":"v11-kibali-mine-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Kibali 大型金礦工程案例中比較碎磨與能量與金回收與產率，各完成分析及驗證。","descriptionEn":"Analyze and validate comminution/energy and gold recovery/yield within the Kibali large gold-mining engineering case.","steps":[{"id":"v11-kibali-mine-v11-05","order":1,"sequence":5,"title":"粒徑解離與破碎：架構分析","titleEn":"Particle size, liberation and comminution: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-04"],"objective":"針對碎磨與能量提出可反駁的粒徑解離與破碎模型與驗證紀錄。","objectiveEn":"Produce a falsifiable particle size, liberation and comminution model and evidence record for comminution/energy.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識碎磨與能量。粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。 建立粒徑解離與破碎的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較假想粒度分佈、解離率與單位能耗。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify comminution/energy in the mentor diagram and primary sources for Kibali large gold-mining engineering. Size reduction can improve liberation while increasing energy/slimes; size is not recovery. Draw the inputs, states, outputs and boundaries of particle size, liberation and comminution, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare assumed size distributions, liberation and specific energy. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較假想粒度分佈、解離率與單位能耗。","observationEn":"Compare assumed size distributions, liberation and specific energy.","failure":"常見誤判：研磨越細就必然提升全部經濟與環境指標。","failureEn":"Common misconception: Finer grinding improves every economic/environmental metric.","check":"提交碎磨與能量的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for comminution/energy.","knowledge":[{"id":"v11-kibali-mine-v11-05-k1","title":"粒徑解離與破碎","titleEn":"Particle size, liberation and comminution","text":"粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。 本課架構對應：碎磨與能量","textEn":"Size reduction can improve liberation while increasing energy/slimes; size is not recovery. Course architecture correspondence: Comminution/energy","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想粒度分佈、解離率與單位能耗。 應逐項保留基準與不確定度；研磨越細就必然提升全部經濟與環境指標。 是本單元要排除的誤解。","textEn":"Compare assumed size distributions, liberation and specific energy. Retain each reference and uncertainty; reject the misconception: Finer grinding improves every economic/environmental metric.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就碎磨與能量的「粒徑解離與破碎」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for particle size, liberation and comminution in comminution/energy?","options":["研磨越細就必然提升全部經濟與環境指標。","粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Finer grinding improves every economic/environmental metric.","Size reduction can improve liberation while increasing energy/slimes; size is not recovery.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。 比較假想粒度分佈、解離率與單位能耗。","explanationEn":"Size reduction can improve liberation while increasing energy/slimes; size is not recovery. Compare assumed size distributions, liberation and specific energy."}},{"id":"v11-kibali-mine-v11-06","order":2,"sequence":6,"title":"粒徑解離與破碎：證據驗證","titleEn":"Particle size, liberation and comminution: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-05"],"objective":"針對碎磨與能量提出可反駁的粒徑解離與破碎模型與驗證紀錄。","objectiveEn":"Produce a falsifiable particle size, liberation and comminution model and evidence record for comminution/energy.","instruction":"沿用前一步「粒徑解離與破碎」模型，檢查碎磨與能量的兩個假想案例。比較假想粒度分佈、解離率與單位能耗。 先訂可接受誤差，再比較預測與獨立計算；區分粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous particle size, liberation and comminution model to inspect two hypothetical cases involving comminution/energy. Compare assumed size distributions, liberation and specific energy. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Size reduction can improve liberation while increasing energy/slimes; size is not recovery.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較假想粒度分佈、解離率與單位能耗。","observationEn":"Compare assumed size distributions, liberation and specific energy.","failure":"常見誤判：研磨越細就必然提升全部經濟與環境指標。","failureEn":"Common misconception: Finer grinding improves every economic/environmental metric.","check":"提交碎磨與能量的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for comminution/energy.","knowledge":[{"id":"v11-kibali-mine-v11-06-k1","title":"粒徑解離與破碎","titleEn":"Particle size, liberation and comminution","text":"粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。 本課架構對應：碎磨與能量","textEn":"Size reduction can improve liberation while increasing energy/slimes; size is not recovery. Course architecture correspondence: Comminution/energy","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想粒度分佈、解離率與單位能耗。 應逐項保留基準與不確定度；研磨越細就必然提升全部經濟與環境指標。 是本單元要排除的誤解。","textEn":"Compare assumed size distributions, liberation and specific energy. Retain each reference and uncertainty; reject the misconception: Finer grinding improves every economic/environmental metric.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就碎磨與能量的「粒徑解離與破碎」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for particle size, liberation and comminution in comminution/energy?","options":["研磨越細就必然提升全部經濟與環境指標。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較假想粒度分佈、解離率與單位能耗。"],"optionsEn":["Finer grinding improves every economic/environmental metric.","Equal case averages rule out spatial, temporal and model errors.","Compare assumed size distributions, liberation and specific energy."],"answer":2,"explanation":"粒徑減小可能提高解離但增加能耗與細泥；粒度不是金屬回收率。 比較假想粒度分佈、解離率與單位能耗。","explanationEn":"Size reduction can improve liberation while increasing energy/slimes; size is not recovery. Compare assumed size distributions, liberation and specific energy."}},{"id":"v11-kibali-mine-v11-07","order":3,"sequence":7,"title":"重力選別與質量收支：架構分析","titleEn":"Gravity separation and mass balance: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-06"],"objective":"針對金回收與產率提出可反駁的重力選別與質量收支模型與驗證紀錄。","objectiveEn":"Produce a falsifiable gravity separation and mass balance model and evidence record for gold recovery/yield.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識金回收與產率。密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。 建立重力選別與質量收支的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用給定假想給料與精礦計算金屬守恆。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify gold recovery/yield in the mentor diagram and primary sources for Kibali large gold-mining engineering. Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ. Draw the inputs, states, outputs and boundaries of gravity separation and mass balance, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Check metal balance from assumed feed/concentrate data. Record units, undisclosed parameters and model breakdown conditions.","observation":"用給定假想給料與精礦計算金屬守恆。","observationEn":"Check metal balance from assumed feed/concentrate data.","failure":"常見誤判：精礦品位越高就保證回收金屬越多。","failureEn":"Common misconception: Higher concentrate grade guarantees more metal recovered.","check":"提交金回收與產率的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for gold recovery/yield.","knowledge":[{"id":"v11-kibali-mine-v11-07-k1","title":"重力選別與質量收支","titleEn":"Gravity separation and mass balance","text":"密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。 本課架構對應：金回收與產率","textEn":"Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ. Course architecture correspondence: Gold recovery/yield","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用給定假想給料與精礦計算金屬守恆。 應逐項保留基準與不確定度；精礦品位越高就保證回收金屬越多。 是本單元要排除的誤解。","textEn":"Check metal balance from assumed feed/concentrate data. Retain each reference and uncertainty; reject the misconception: Higher concentrate grade guarantees more metal recovered.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就金回收與產率的「重力選別與質量收支」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for gravity separation and mass balance in gold recovery/yield?","options":["密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。","精礦品位越高就保證回收金屬越多。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ.","Higher concentrate grade guarantees more metal recovered.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。 用給定假想給料與精礦計算金屬守恆。","explanationEn":"Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ. Check metal balance from assumed feed/concentrate data."}},{"id":"v11-kibali-mine-v11-08","order":4,"sequence":8,"title":"重力選別與質量收支：證據驗證","titleEn":"Gravity separation and mass balance: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-07"],"objective":"針對金回收與產率提出可反駁的重力選別與質量收支模型與驗證紀錄。","objectiveEn":"Produce a falsifiable gravity separation and mass balance model and evidence record for gold recovery/yield.","instruction":"沿用前一步「重力選別與質量收支」模型，檢查金回收與產率的兩個假想案例。用給定假想給料與精礦計算金屬守恆。 先訂可接受誤差，再比較預測與獨立計算；區分密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous gravity separation and mass balance model to inspect two hypothetical cases involving gold recovery/yield. Check metal balance from assumed feed/concentrate data. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用給定假想給料與精礦計算金屬守恆。","observationEn":"Check metal balance from assumed feed/concentrate data.","failure":"常見誤判：精礦品位越高就保證回收金屬越多。","failureEn":"Common misconception: Higher concentrate grade guarantees more metal recovered.","check":"提交金回收與產率的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for gold recovery/yield.","knowledge":[{"id":"v11-kibali-mine-v11-08-k1","title":"重力選別與質量收支","titleEn":"Gravity separation and mass balance","text":"密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。 本課架構對應：金回收與產率","textEn":"Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ. Course architecture correspondence: Gold recovery/yield","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用給定假想給料與精礦計算金屬守恆。 應逐項保留基準與不確定度；精礦品位越高就保證回收金屬越多。 是本單元要排除的誤解。","textEn":"Check metal balance from assumed feed/concentrate data. Retain each reference and uncertainty; reject the misconception: Higher concentrate grade guarantees more metal recovered.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就金回收與產率的「重力選別與質量收支」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for gravity separation and mass balance in gold recovery/yield?","options":["精礦品位越高就保證回收金屬越多。","用給定假想給料與精礦計算金屬守恆。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Higher concentrate grade guarantees more metal recovered.","Check metal balance from assumed feed/concentrate data.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"密度、粒徑及形狀共同影響重力分離；精礦品位、產率與回收率不同。 用給定假想給料與精礦計算金屬守恆。","explanationEn":"Density, size and shape affect gravity separation; concentrate grade, yield and recovery differ. Check metal balance from assumed feed/concentrate data."}}]},{"id":"v11-kibali-mine-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Kibali 大型金礦工程案例中比較礦山支援與電力與尾礦水與生命週期，各完成分析及驗證。","descriptionEn":"Analyze and validate mine support/electricity and tailings/water/lifecycle within the Kibali large gold-mining engineering case.","steps":[{"id":"v11-kibali-mine-v11-09","order":1,"sequence":9,"title":"通風電力與自動化：架構分析","titleEn":"Ventilation, power and automation: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-08"],"objective":"針對礦山支援與電力提出可反駁的通風電力與自動化模型與驗證紀錄。","objectiveEn":"Produce a falsifiable ventilation, power and automation model and evidence record for mine support/electricity.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識礦山支援與電力。地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。 建立通風電力與自動化的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較失去一項支援時的概念依賴，不操作真實礦井。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify mine support/electricity in the mentor diagram and primary sources for Kibali large gold-mining engineering. Ventilation/power support underground work; automated haulage needs sensing, communications and separation. Draw the inputs, states, outputs and boundaries of ventilation, power and automation, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare conceptual lost-support dependencies without operating a mine. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較失去一項支援時的概念依賴，不操作真實礦井。","observationEn":"Compare conceptual lost-support dependencies without operating a mine.","failure":"常見誤判：自動化設備無需人員與道路隔離設計。","failureEn":"Common misconception: Automated equipment needs no people/route separation design.","check":"提交礦山支援與電力的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for mine support/electricity.","knowledge":[{"id":"v11-kibali-mine-v11-09-k1","title":"通風電力與自動化","titleEn":"Ventilation, power and automation","text":"地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。 本課架構對應：礦山支援與電力","textEn":"Ventilation/power support underground work; automated haulage needs sensing, communications and separation. Course architecture correspondence: Mine support/electricity","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較失去一項支援時的概念依賴，不操作真實礦井。 應逐項保留基準與不確定度；自動化設備無需人員與道路隔離設計。 是本單元要排除的誤解。","textEn":"Compare conceptual lost-support dependencies without operating a mine. Retain each reference and uncertainty; reject the misconception: Automated equipment needs no people/route separation design.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就礦山支援與電力的「通風電力與自動化」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for ventilation, power and automation in mine support/electricity?","options":["自動化設備無需人員與道路隔離設計。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。"],"optionsEn":["Automated equipment needs no people/route separation design.","Equal case averages rule out spatial, temporal and model errors.","Ventilation/power support underground work; automated haulage needs sensing, communications and separation."],"answer":2,"explanation":"地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。 比較失去一項支援時的概念依賴，不操作真實礦井。","explanationEn":"Ventilation/power support underground work; automated haulage needs sensing, communications and separation. Compare conceptual lost-support dependencies without operating a mine."}},{"id":"v11-kibali-mine-v11-10","order":2,"sequence":10,"title":"通風電力與自動化：證據驗證","titleEn":"Ventilation, power and automation: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-09"],"objective":"針對礦山支援與電力提出可反駁的通風電力與自動化模型與驗證紀錄。","objectiveEn":"Produce a falsifiable ventilation, power and automation model and evidence record for mine support/electricity.","instruction":"沿用前一步「通風電力與自動化」模型，檢查礦山支援與電力的兩個假想案例。比較失去一項支援時的概念依賴，不操作真實礦井。 先訂可接受誤差，再比較預測與獨立計算；區分地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous ventilation, power and automation model to inspect two hypothetical cases involving mine support/electricity. Compare conceptual lost-support dependencies without operating a mine. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Ventilation/power support underground work; automated haulage needs sensing, communications and separation.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較失去一項支援時的概念依賴，不操作真實礦井。","observationEn":"Compare conceptual lost-support dependencies without operating a mine.","failure":"常見誤判：自動化設備無需人員與道路隔離設計。","failureEn":"Common misconception: Automated equipment needs no people/route separation design.","check":"提交礦山支援與電力的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for mine support/electricity.","knowledge":[{"id":"v11-kibali-mine-v11-10-k1","title":"通風電力與自動化","titleEn":"Ventilation, power and automation","text":"地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。 本課架構對應：礦山支援與電力","textEn":"Ventilation/power support underground work; automated haulage needs sensing, communications and separation. Course architecture correspondence: Mine support/electricity","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較失去一項支援時的概念依賴，不操作真實礦井。 應逐項保留基準與不確定度；自動化設備無需人員與道路隔離設計。 是本單元要排除的誤解。","textEn":"Compare conceptual lost-support dependencies without operating a mine. Retain each reference and uncertainty; reject the misconception: Automated equipment needs no people/route separation design.","sourceIds":["v11x-kibali","v11x-gold"]}],"quiz":{"question":"就礦山支援與電力的「通風電力與自動化」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for ventilation, power and automation in mine support/electricity?","options":["比較失去一項支援時的概念依賴，不操作真實礦井。","自動化設備無需人員與道路隔離設計。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Compare conceptual lost-support dependencies without operating a mine.","Automated equipment needs no people/route separation design.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"地下通風與電力是支援系統；自動搬運需感測、通信與人員隔離。 比較失去一項支援時的概念依賴，不操作真實礦井。","explanationEn":"Ventilation/power support underground work; automated haulage needs sensing, communications and separation. Compare conceptual lost-support dependencies without operating a mine."}},{"id":"v11-kibali-mine-v11-11","order":3,"sequence":11,"title":"尾礦水與復育：架構分析","titleEn":"Tailings, water and rehabilitation: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-10"],"objective":"針對尾礦水與生命週期提出可反駁的尾礦水與復育模型與驗證紀錄。","objectiveEn":"Produce a falsifiable tailings, water and rehabilitation model and evidence record for tailings/water/lifecycle.","instruction":"在「Kibali 大型金礦工程」的師傅示意與公開來源中，先辨識尾礦水與生命週期。尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。 建立尾礦水與復育的輸入、狀態、輸出及邊界圖；本課重點是多路徑採礦、支援電力與回收證據。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較假想水與固體收支及修復證據。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify tailings/water/lifecycle in the mentor diagram and primary sources for Kibali large gold-mining engineering. Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints. Draw the inputs, states, outputs and boundaries of tailings, water and rehabilitation, focusing on multiple mining routes, support power and recovery evidence. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare assumed water/solids balance and rehabilitation evidence. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較假想水與固體收支及修復證據。","observationEn":"Compare assumed water/solids balance and rehabilitation evidence.","failure":"常見誤判：回收率高表示尾礦與礦水沒有影響。","failureEn":"Common misconception: High recovery means tailings/water have no impact.","check":"提交尾礦水與生命週期的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for tailings/water/lifecycle.","knowledge":[{"id":"v11-kibali-mine-v11-11-k1","title":"尾礦水與復育","titleEn":"Tailings, water and rehabilitation","text":"尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。 本課架構對應：尾礦水與生命週期","textEn":"Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints. Course architecture correspondence: Tailings/water/lifecycle","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想水與固體收支及修復證據。 應逐項保留基準與不確定度；回收率高表示尾礦與礦水沒有影響。 是本單元要排除的誤解。","textEn":"Compare assumed water/solids balance and rehabilitation evidence. Retain each reference and uncertainty; reject the misconception: High recovery means tailings/water have no impact.","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設乾給料1100 t、品位1.5 g/t、金屬回收率0.85，可回收金屬=1402.5 g=1.4025 kg。回收率不同於精礦品位；未含礦物解離、處理成本或任何浸出配方，非礦場實測。","textEn":"Assume dry feed 1100 t, grade 1.5 g/t and metal recovery 0.85: recovered metal 1402.5 g=1.4025 kg. Recovery differs from concentrate grade; liberation/costs and all leaching recipes are excluded; this is not a mine measurement.","sourceIds":["v11x-kibali","v11x-gold"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就尾礦水與生命週期的「尾礦水與復育」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for tailings, water and rehabilitation in tailings/water/lifecycle?","options":["回收率高表示尾礦與礦水沒有影響。","尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["High recovery means tailings/water have no impact.","Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。 比較假想水與固體收支及修復證據。","explanationEn":"Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints. Compare assumed water/solids balance and rehabilitation evidence."}},{"id":"v11-kibali-mine-v11-12","order":4,"sequence":12,"title":"尾礦水與復育：證據驗證","titleEn":"Tailings, water and rehabilitation: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-kibali","v11x-gold"],"prerequisiteIds":["v11-kibali-mine-v11-11"],"objective":"針對尾礦水與生命週期提出可反駁的尾礦水與復育模型與驗證紀錄。","objectiveEn":"Produce a falsifiable tailings, water and rehabilitation model and evidence record for tailings/water/lifecycle.","instruction":"沿用前一步「尾礦水與復育」模型，檢查尾礦水與生命週期的兩個假想案例。比較假想水與固體收支及修復證據。 先訂可接受誤差，再比較預測與獨立計算；區分尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous tailings, water and rehabilitation model to inspect two hypothetical cases involving tailings/water/lifecycle. Compare assumed water/solids balance and rehabilitation evidence. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較假想水與固體收支及修復證據。","observationEn":"Compare assumed water/solids balance and rehabilitation evidence.","failure":"常見誤判：回收率高表示尾礦與礦水沒有影響。","failureEn":"Common misconception: High recovery means tailings/water have no impact.","check":"提交尾礦水與生命週期的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for tailings/water/lifecycle.","knowledge":[{"id":"v11-kibali-mine-v11-12-k1","title":"尾礦水與復育","titleEn":"Tailings, water and rehabilitation","text":"尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。 本課架構對應：尾礦水與生命週期","textEn":"Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints. Course architecture correspondence: Tailings/water/lifecycle","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想水與固體收支及修復證據。 應逐項保留基準與不確定度；回收率高表示尾礦與礦水沒有影響。 是本單元要排除的誤解。","textEn":"Compare assumed water/solids balance and rehabilitation evidence. Retain each reference and uncertainty; reject the misconception: High recovery means tailings/water have no impact.","sourceIds":["v11x-kibali","v11x-gold"]},{"id":"v11-kibali-mine-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設乾給料1100 t、品位1.5 g/t、金屬回收率0.85，可回收金屬=1402.5 g=1.4025 kg。回收率不同於精礦品位；未含礦物解離、處理成本或任何浸出配方，非礦場實測。","textEn":"Assume dry feed 1100 t, grade 1.5 g/t and metal recovery 0.85: recovered metal 1402.5 g=1.4025 kg. Recovery differs from concentrate grade; liberation/costs and all leaching recipes are excluded; this is not a mine measurement.","sourceIds":["v11x-kibali","v11x-gold"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就尾礦水與生命週期的「尾礦水與復育」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for tailings, water and rehabilitation in tailings/water/lifecycle?","options":["回收率高表示尾礦與礦水沒有影響。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較假想水與固體收支及修復證據。"],"optionsEn":["High recovery means tailings/water have no impact.","Equal case averages rule out spatial, temporal and model errors.","Compare assumed water/solids balance and rehabilitation evidence."],"answer":2,"explanation":"尾礦與礦水需質量平衡、監測與長期管理；回收目標不替代環境約束。 比較假想水與固體收支及修復證據。","explanationEn":"Tailings/water need balance, monitoring and long-term management; recovery targets do not replace environmental constraints. Compare assumed water/solids balance and rehabilitation evidence."}}]}],"summary":"以多路徑採礦、支援電力與回收證據解析Kibali 大型金礦工程：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Kibali large gold-mining engineering through multiple mining routes, support power and recovery evidence: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"公開資源工程的離線質量、能量及環境證據判讀；不提供鑽井、井控、採掘、爆破或危險化學浸出SOP。採礦權、許可、地質完整性與現場規範需由合格團隊另行確認，課程完成不是操作資格。","scopeEn":"Offline public resource-engineering material/energy/environmental analysis; no drilling, well-control, excavation, blasting or hazardous-leaching SOP. Qualified teams separately establish rights, permits, integrity and field requirements; completion is not operating qualification.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假設乾給料1100 t、品位1.5 g/t、金屬回收率0.85，可回收金屬=1402.5 g=1.4025 kg。回收率不同於精礦品位；未含礦物解離、處理成本或任何浸出配方，非礦場實測。","textEn":"Assume dry feed 1100 t, grade 1.5 g/t and metal recovery 0.85: recovered metal 1402.5 g=1.4025 kg. Recovery differs from concentrate grade; liberation/costs and all leaching recipes are excluded; this is not a mine measurement.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"power","labels":["Kibali資源grade","露天地下path區別","碎磨與能量","金回收與產率","礦山支援與電力","尾礦水與生命週期"],"labelsEn":["Kibali resource grades","Surface/underground paths","Comminution/energy","Gold recovery/yield","Mine support/electricity","Tailings/water/lifecycle"],"original":true,"notToScale":true},"vendorHints":[{"name":"Barrick","nameEn":"Barrick","url":"https://www.barrick.com/English/operations/kibali/","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-kibali"]},{"name":"U.S. Geological Survey","nameEn":"U.S. Geological Survey","url":"https://www.usgs.gov/centers/national-minerals-information-center/gold-statistics-and-information","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-gold"]}],"architectureNodes":[["礦體與樣本","Orebody/samples"],["物料搬運","Material handling"],["解離與選別","Liberation/separation"],["回收物料","Recovered materials"],["礦水尾礦管理","Water/tailings management"]],"architectureEdges":[[0,1],[1,2],[2,3],[2,4]],"architectureFamily":"mining","educationEdition":11,"enrichmentVersion":11}};
